insert into public.scam_patterns (id, label, description, severity, category, keywords) values
  ('urgencia_artificial', 'Urgência artificial', 'Criam senso de urgência para impedir que você pense com calma ou confirme com outra pessoa.', 'alto', 'pressao_psicologica', ARRAY['urgente', 'imediatamente', 'agora mesmo', 'últimos minutos', 'expira hoje', 'até às \d', 'em \d+ minutos']::text[]),
  ('ameaca', 'Ameaça', 'Uso de ameaças (bloqueio, multa, prisão, corte de serviço) para gerar medo.', 'alto', 'pressao_psicologica', ARRAY['será bloquead', 'conta será encerrada', 'você será preso', 'ação judicial', 'processo criminal', 'multa de', 'suspens[ãa]o']::text[]),
  ('medo', 'Indução de medo', 'Mensagem construída para provocar pânico e reduzir a capacidade de análise crítica.', 'medio', 'pressao_psicologica', ARRAY['não conte para ningu[ée]m', 'não desligue', 'não fale com ningu[ée]m', 'segredo', 'perigo']::text[]),
  ('promessa_dinheiro', 'Promessa de dinheiro fácil', 'Oferece dinheiro, prêmio ou retorno financeiro incomum.', 'alto', 'pressao_psicologica', ARRAY['voc[êe] ganhou', 'pr[êe]mio', 'sorteio', 'dinheiro fácil', 'renda extra garantida', 'retorno de \d+%']::text[]),
