  ('pedido_senha', 'Pedido de senha', 'Solicitação de senha de aplicativos, e-mail ou bancos.', 'alto', 'pedido_de_dados_ou_dinheiro', ARRAY['me (envia|passa|manda) (a |sua )?senha', 'informe sua senha', 'confirme sua senha']::text[]),
