  ('investimento_fraudulento', 'Possível investimento fraudulento', 'Promessa de retorno financeiro alto, rápido e "garantido" — incompatível com investimentos reais.', 'alto', 'financeiro', ARRAY['retorno garantido', 'lucro garantido', 'sem risco', '\d+% ao (m[êe]s|dia)']::text[]),
  ('piramide_financeira', 'Possível pirâmide financeira', 'Modelo que depende de recrutar novos participantes para gerar retorno.', 'alto', 'financeiro', ARRAY['indique (amigos|pessoas) e ganhe', 'sistema de indica[çc][ãa]o', 'multin[íi]vel']::text[]),
