  ('golpe_aluguel', 'Golpe de aluguel', 'Anúncio de aluguel com preço muito abaixo do mercado, exigindo pagamento adiantado sem visita.', 'alto', 'contexto_especifico', ARRAY['alugo sem fiador', 'chave mediante dep[óo]sito', 'n[ãa]o precisa visitar']::text[]),
