  ('clonagem_conta', 'Sinal de clonagem/roubo de conta', 'Indícios de que uma conta (WhatsApp, redes sociais) foi clonada ou tomada por terceiros.', 'alto', 'contexto_especifico', ARRAY['minha conta foi clonada', 'perdi acesso [àa] minha conta', 'n[ãa]o consigo entrar no whatsapp']::text[]),
